11	// Logical column types supported by the format. The physical layout of every
12	// type is documented in README.md ("Page payload layout").
13	const (
14		TypeInt64   = "int64"
15		TypeFloat64 = "float64"
16		TypeBool    = "bool"
17		TypeString  = "string"
18	)
