33	func (s Schema) Column(name string) (Column, bool) {
34		for _, c := range s.Columns {
35			if c.Name == name {
36				return c, true
37			}
38		}
39		return Column{}, false
40	}
41	
42	// columnIndex returns the position of a column inside a schema, or -1.
43	func columnIndex(schema Schema, name string) int {
44		for i, c := range schema.Columns {
45			if c.Name == name {
46				return i
47			}
48		}
49		return -1
50	}
51	
52	// nonNullIndices lists the positions of the non-null values.
53	func nonNullIndices(values []Value) []int {
54		out := make([]int, 0, len(values))
55		for i := range values {
56			if !values[i].Null {
57				out = append(out, i)
58			}
59		}
60		return out
61	}
