63	// ValidName reports whether a table or column name is accepted.
64	func ValidName(name string) bool {
65		if name == "" || len(name) > 64 {
66			return false
67		}
68		for i, r := range name {
69			switch {
70			case r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r == '_':
71			case r >= '0' && r <= '9' && i > 0:
72			default:
73				return false
74			}
75		}
76		return true
77	}
