87	func (s Schema) Validate() error {
88		if len(s.Columns) == 0 {
89			return Validationf("schema must define at least one column")
90		}
91		if len(s.Columns) > 512 {
92			return Validationf("schema has %d columns, the limit is 512", len(s.Columns))
93		}
94		seen := map[string]bool{}
95		for i, c := range s.Columns {
96			if !ValidName(c.Name) {
97				return Validationf("column %d has an invalid name %q", i, c.Name)
98			}
99			if seen[c.Name] {
100				return Validationf("duplicate column %q", c.Name)
101			}
102			seen[c.Name] = true
103			if !validType(c.Type) {
104				return Validationf("column %q has unsupported type %q", c.Name, c.Type)
105			}
106		}
107		return nil
108	}
109	
110	func (s Schema) Equal(other Schema) bool {
111		if len(s.Columns) != len(other.Columns) {
112			return false
113		}
114		for i := range s.Columns {
115			if s.Columns[i] != other.Columns[i] {
116				return false
117			}
118		}
119		return true
120	}
121	
122	// Value is one cell. Exactly one of the typed fields is meaningful, selected
123	// by Kind; Null reports SQL NULL.
124	type Value struct {
125		Null  bool
126		Kind  string
127		Int   int64
128		Float float64
129		Bool  bool
130		Str   string
131	}
132	
133	func NullValue() Value           { return Value{Null: true} }
134	func IntValue(v int64) Value     { return Value{Kind: TypeInt64, Int: v} }
135	func FloatValue(v float64) Value { return Value{Kind: TypeFloat64, Float: v} }
136	func BoolValue(v bool) Value     { return Value{Kind: TypeBool, Bool: v} }
137	func StringValue(v string) Value { return Value{Kind: TypeString, Str: v} }
138	
139	// UnmarshalJSON decodes a JSON scalar into a typed value. The kind is inferred
140	// from the JSON token: booleans and strings keep their type, and numbers become
141	// int64 when they are written without a fraction or exponent and fit an int64,
142	// otherwise float64. Objects, arrays and non-finite numbers are rejected.
143	func (v *Value) UnmarshalJSON(raw []byte) error {
144		trimmed := bytes.TrimSpace(raw)
145		if len(trimmed) == 0 {
146			return Validationf("value must be a JSON scalar")
147		}
148		switch trimmed[0] {
149		case 'n':
150			if string(trimmed) != "null" {
151				return Validationf("value must be a JSON scalar")
152			}
153			*v = NullValue()
154			return nil
155		case 't', 'f':
156			var b bool
157			if err := json.Unmarshal(trimmed, &b); err != nil {
158				return Validationf("value must be a JSON scalar")
159			}
160			*v = BoolValue(b)
161			return nil
162		case '"':
163			var s string
164			if err := json.Unmarshal(trimmed, &s); err != nil {
165				return Validationf("value must be a JSON string")
166			}
167			if containsNUL(s) {
168				return Validationf("value must not contain NUL bytes")
169			}
170			*v = StringValue(s)
171			return nil
172		case '{', '[':
173			return Validationf("value must be a JSON scalar")
174		default:
175			var number json.Number
176			if err := json.Unmarshal(trimmed, &number); err != nil {
177				return Validationf("value must be a number")
178			}
179			if !strings.ContainsAny(number.String(), ".eE") {
180				if i, err := number.Int64(); err == nil {
181					*v = IntValue(i)
182					return nil
183				}
184			}
185			f, err := number.Float64()
186			if err != nil {
187				return Validationf("value must be a number")
188			}
189			if math.IsNaN(f) || math.IsInf(f, 0) {
190				return Validationf("value must be finite")
191			}
192			*v = FloatValue(f)
193			return nil
194		}
195	}
196	
197	// Number returns the numeric view of an int64 or float64 value.
198	func (v Value) Number() (float64, bool) {
199		switch v.Kind {
200		case TypeInt64:
201			return float64(v.Int), true
202		case TypeFloat64:
203			return v.Float, true
204		}
205		return 0, false
206	}
207	
208	// JSON renders the value for API responses and CLI output.
209	func (v Value) JSON() any {
210		if v.Null {
211			return nil
212		}
213		switch v.Kind {
214		case TypeInt64:
215			return v.Int
216		case TypeFloat64:
217			return v.Float
218		case TypeBool:
219			return v.Bool
220		default:
221			return v.Str
222		}
223	}
224	
225	// Row is an ordered list of cells, one per schema column.
226	type Row []Value
227	
228	func (r Row) JSON(schema Schema) map[string]any {
229		out := make(map[string]any, len(r))
230		for i, c := range schema.Columns {
231			if i < len(r) {
232				out[c.Name] = r[i].JSON()
233			}
234		}
235		return out
236	}
237	
238	// DecodeLines converts a JSONL file (one JSON object per line) or a JSON array
239	// into typed rows.
240	func DecodeLines(schema Schema, raw []byte) ([]Row, error) {
241		trimmed := bytes.TrimSpace(raw)
242		if len(trimmed) == 0 {
243			return nil, Validationf("input is empty")
244		}
245		if trimmed[0] == '[' {
246			return DecodeRows(schema, json.RawMessage(trimmed))
247		}
248		rows := []Row{}
249		for number, line := range bytes.Split(trimmed, []byte("\n")) {
250			line = bytes.TrimSpace(line)
251			if len(line) == 0 {
252				continue
253			}
254			var item map[string]json.RawMessage
255			if err := unmarshalStrict(json.RawMessage(line), &item); err != nil {
256				return nil, Validationf("line %d is not a JSON object: %v", number+1, err)
257			}
258			row, err := DecodeRow(schema, item)
259			if err != nil {
260				return nil, Validationf("line %d: %s", number+1, err.Error())
261			}
262			rows = append(rows, row)
263		}
264		return rows, nil
265	}
266	
267	// DecodeRows converts a JSON message into typed rows for the schema. Unknown
268	// keys, missing keys, non-nullable nulls and type mismatches are rejected.
269	func DecodeRows(schema Schema, raw json.RawMessage) ([]Row, error) {
270		var items []map[string]json.RawMessage
271		if err := unmarshalStrict(raw, &items); err != nil {
272			return nil, Validationf("rows must be a JSON array of objects: %v", err)
273		}
274		rows := make([]Row, 0, len(items))
275		for i, item := range items {
276			row, err := DecodeRow(schema, item)
277			if err != nil {
278				return nil, Validationf("row %d: %s", i, err.Error())
279			}
280			rows = append(rows, row)
281		}
282		return rows, nil
283	}
284	
285	// DecodeRow converts one decoded JSON object into a typed row.
286	func DecodeRow(schema Schema, item map[string]json.RawMessage) (Row, error) {
287		known := map[string]Column{}
288		for _, c := range schema.Columns {
289			known[c.Name] = c
290		}
291		for key := range item {
292			if _, ok := known[key]; !ok {
293				return nil, Validationf("unknown field %q", key)
294			}
295		}
296		row := make(Row, len(schema.Columns))
297		for i, c := range schema.Columns {
298			raw, ok := item[c.Name]
299			if !ok {
300				return nil, Validationf("missing field %q", c.Name)
301			}
302			value, err := decodeCell(c, raw)
303			if err != nil {
304				return nil, err
305			}
306			row[i] = value
307		}
308		return row, nil
309	}
310	
311	func decodeCell(c Column, raw json.RawMessage) (Value, error) {
312		if string(raw) == "null" {
313			if !c.Nullable {
314				return Value{}, Validationf("column %q is not nullable", c.Name)
315			}
316			return NullValue(), nil
317		}
318		switch c.Type {
319		case TypeInt64:
320			var number json.Number
321			if err := json.Unmarshal(raw, &number); err != nil {
322				return Value{}, Validationf("column %q expects an int64", c.Name)
323			}
324			v, err := number.Int64()
325			if err != nil {
326				return Value{}, Validationf("column %q expects an int64, got %s", c.Name, number.String())
327			}
328			return IntValue(v), nil
329		case TypeFloat64:
330			var number json.Number
331			if err := json.Unmarshal(raw, &number); err != nil {
332				return Value{}, Validationf("column %q expects a float64", c.Name)
333			}
334			v, err := number.Float64()
335			if err != nil {
336				return Value{}, Validationf("column %q expects a float64, got %s", c.Name, number.String())
337			}
338			if math.IsInf(v, 0) || math.IsNaN(v) {
339				return Value{}, Validationf("column %q rejects non-finite values", c.Name)
340			}
341			return FloatValue(v), nil
342		case TypeBool:
343			var b bool
344			if err := json.Unmarshal(raw, &b); err != nil {
345				return Value{}, Validationf("column %q expects a bool", c.Name)
346			}
347			return BoolValue(b), nil
348		default:
349			var s string
350			if err := json.Unmarshal(raw, &s); err != nil {
351				return Value{}, Validationf("column %q expects a string", c.Name)
352			}
353			if containsNUL(s) {
354				return Value{}, Validationf("column %q rejects embedded NUL bytes", c.Name)
355			}
356			return StringValue(s), nil
357		}
358	}
359	
360	func containsNUL(s string) bool {
361		for i := 0; i < len(s); i++ {
362			if s[i] == 0 {
363				return true
364			}
365		}
366		return false
367	}
368	
369	func unmarshalStrict(raw json.RawMessage, target any) error {
370		decoder := json.NewDecoder(bytes.NewReader(raw))
371		decoder.DisallowUnknownFields()
372		decoder.UseNumber()
373		if err := decoder.Decode(target); err != nil {
374			return err
375		}
376		if _, err := decoder.Token(); err != io.EOF {
377			return errTrailing
378		}
379		return nil
380	}
381	
382	var errTrailing = &Error{Code: CodeValidation, Message: "unexpected trailing data"}
