214				return compareValues(v, *p.Value) == 0
215			}
216		case OpBetween:
217			if typ == TypeString {
218				return v.Str >= p.Lo.Str && v.Str <= p.Hi.Str
219			}
220			return compareValues(v, *p.Lo) >= 0 && compareValues(v, *p.Hi) <= 0
