222			if typ == TypeString {
223				return false // ordering operators are rejected for string columns
224			}
225			cmp := compareValues(v, *p.Value)
226			switch p.Op {
227			case OpLt:
228				return cmp < 0
229			case OpLte:
230				return cmp <= 0
231			case OpGt:
232				return cmp > 0
233			case OpGte:
