243	func compareValues(a, b Value) int {
244		switch {
245		case a.Kind == TypeInt64 && b.Kind == TypeInt64:
246			switch {
247			case a.Int < b.Int:
248				return -1
249			case a.Int > b.Int:
250				return 1
251			default:
252				return 0
253			}
254		case a.Kind == TypeBool && b.Kind == TypeBool:
255			switch {
256			case a.Bool == b.Bool:
257				return 0
258			case !a.Bool:
259				return -1
260			default:
261				return 1
262			}
263		case a.Kind == TypeString && b.Kind == TypeString:
264			switch {
265			case a.Str < b.Str:
266				return -1
267			case a.Str > b.Str:
268				return 1
269			default:
270				return 0
271			}
272		default:
273			x, _ := a.Number()
274			y, _ := b.Number()
275			switch {
276			case x < y:
277				return -1
278			case x > y:
279				return 1
280			default:
281				return 0
282			}
283		}
284	}
285	
286	// pageMatches uses page statistics to decide whether a page can hold a
287	// matching row. It may only return false when no row in the page can match.
288	func (p Predicate) pageMatches(stats PageStats, rows int64) bool {
289		if rows == 0 {
290			return false
291		}
292		if stats.Nulls == rows {
293			return false // every value is NULL, and NULL never matches
294		}
295		if !stats.Set {
296			return true
297		}
298		// The statistics hold the min and max of the non-null values, so an
299		// operator can only match if its value range overlaps [min, max].
300		switch p.Op {
301		case OpBetween:
302			return compareValues(stats.Max, *p.Lo) >= 0 && compareValues(stats.Min, *p.Hi) <= 0
303		case OpEq:
304			return compareValues(stats.Min, *p.Value) <= 0 && compareValues(stats.Max, *p.Value) >= 0
305		case OpLt:
306			return compareValues(stats.Min, *p.Value) < 0
307		case OpLte:
308			return compareValues(stats.Min, *p.Value) <= 0
309		case OpGt:
310			return compareValues(stats.Max, *p.Value) > 0
311		case OpGte:
312			return compareValues(stats.Max, *p.Value) >= 0
313		}
314		return true
315	}
316	
317	func (q Query) bind(table *Table) (Query, error) {
318		if q.Table == "" {
319			return q, Validationf("table is required")
320		}
321		if q.Table != table.Name {
322			return q, Validationf("query targets table %q but table %q was loaded", q.Table, table.Name)
323		}
324		bound := q
325		if len(bound.Projection) == 0 && len(bound.Aggregates) == 0 {
326			for _, c := range table.Schema.Columns {
327				bound.Projection = append(bound.Projection, c.Name)
328			}
329		}
330		if len(bound.Aggregates) > 0 && len(q.Projection) > 0 {
331			return bound, Validationf("projection and aggregates are mutually exclusive")
332		}
333		for _, name := range bound.Projection {
334			if _, ok := table.Schema.Column(name); !ok {
335				return bound, Validationf("unknown column %q in projection", name)
336			}
337		}
338		for i := range bound.Predicates {
339			bound.Predicates[i].Column = strings.TrimSpace(bound.Predicates[i].Column)
340			predicate, err := bound.Predicates[i].bind(table.Schema)
341			if err != nil {
342				return bound, err
343			}
344			bound.Predicates[i] = predicate
345		}
346		for i, aggregate := range bound.Aggregates {
347			if !validAggs[aggregate.Func] {
348				return bound, Validationf("unsupported aggregate %q", aggregate.Func)
349			}
350			if aggregate.Func == AggCount && aggregate.Column == "" {
351				continue
352			}
353			column, ok := table.Schema.Column(aggregate.Column)
354			if !ok {
355				return bound, Validationf("unknown column %q in aggregate %d", aggregate.Column, i)
356			}
357			if aggregate.Func == AggSum && column.Type != TypeInt64 && column.Type != TypeFloat64 {
358				return bound, Validationf("sum requires an int64 or float64 column, got %s", column.Type)
359			}
360		}
361		if bound.Limit != nil && *bound.Limit < 0 {
362			return bound, Validationf("limit must not be negative")
363		}
364		if bound.Pages != nil && *bound.Pages < 0 {
365			return bound, Validationf("max_pages_per_group must not be negative")
366		}
367		return bound, nil
368	}
