11	func (p *Predicate) UnmarshalJSON(raw []byte) error {
12		var fields map[string]json.RawMessage
13		if err := unmarshalStrict(raw, &fields); err != nil {
14			return Validationf("invalid predicate: %v", err)
15		}
16		decoded, err := decodePredicate(fields)
17		if err != nil {
18			return err
19		}
20		*p = decoded
21		return nil
22	}
