24	// DecodeQuery parses a POST /query body.
25	func DecodeQuery(raw json.RawMessage) (Query, error) {
26		var query Query
27		if err := unmarshalStrict(raw, &query); err != nil {
28			return Query{}, Validationf("invalid query: %v", err)
29		}
30		return query, nil
31	}
32	
33	// decodedSegment holds the values of one decoded page together with the
34	// absolute row offset the page starts at inside its row group.
35	type decodedSegment struct {
36		start  int
37		values []Value
38	}
39	
40	// decodedColumn holds the decoded pages of one column. Pushdown may skip pages
41	// in the middle of a row group, so a column is a list of segments rather than
42	// one contiguous run of values.
43	type decodedColumn struct {
44		// needed reports whether the query reads this column at all (projection,
45		// predicate or aggregate). Rows are only required to be present for needed
46		// columns.
47		needed bool
48		// segments holds the decoded pages in page index order.
49		segments []decodedSegment
50	}
51	
52	// valueAt returns the value of one row, or false when the row lies in a page
53	// that was not decoded.
54	func (c decodedColumn) valueAt(row int) (Value, bool) {
55		index := sort.Search(len(c.segments), func(i int) bool { return c.segments[i].start > row })
56		if index == 0 {
57			return Value{}, false
58		}
59		segment := c.segments[index-1]
60		offset := row - segment.start
61		if offset < 0 || offset >= len(segment.values) {
62			return Value{}, false
63		}
64		return segment.values[offset], true
65	}
66	
67	type decodeStats struct {
68		decodedPages int
69		skippedPages int
70	}
71	
72	// Execute binds and runs a query against one table.
73	//
74	// With pushdown enabled, every page whose recorded min/max statistics cannot
75	// satisfy a predicate is skipped before it is decoded, and a row group without
76	// surviving pages is skipped entirely. Predicate evaluation itself only looks
77	// at decoded values, so pushdown never changes the result set; it only changes
78	// how many pages and rows are touched.
79	func Execute(table *Table, query Query) (QueryResult, error) {
80		bound, err := query.bind(table)
81		if err != nil {
82			return QueryResult{}, err
83		}
84		pushdown := true
85		if bound.Pushdown != nil {
86			pushdown = *bound.Pushdown
87		}
88		if len(bound.Aggregates) > 0 {
89			return executeAggregates(table, bound, pushdown)
90		}
91	
92		result := QueryResult{
93			Columns:  append([]string{}, bound.Projection...),
94			Rows:     []map[string]any{},
95			Pushdown: pushdown,
96		}
97		limit := -1
98		if bound.Limit != nil {
99			limit = *bound.Limit
100		}
101		projection := columnIndices(table.Schema, bound.Projection)
102	
103		stop := false
104		for groupIndex := range table.parsed.rowGroups {
105			if stop {
106				break
107			}
108			group := table.parsed.rowGroups[groupIndex]
109			if group.RowCount == 0 {
110				continue
111			}
112			result.ScannedGroups++
113			columns, stats, err := decodeGroup(table, group, bound, pushdown)
114			if err != nil {
115				return QueryResult{}, err
116			}
117			result.ScannedPages += stats.decodedPages
118			result.SkippedPages += stats.skippedPages
119	
120			examined, err := scanGroup(table.Schema, group.RowCount, columns, bound.Predicates, func(_ int, values []Value) bool {
121				if limit >= 0 && len(result.Rows) >= limit {
122					stop = true
123					return false
124				}
125				row := make(map[string]any, len(projection))
126				for _, index := range projection {
127					row[table.Schema.Columns[index].Name] = values[index].JSON()
128				}
129				result.Rows = append(result.Rows, row)
130				result.MatchedRows++
131				return true
132			})
133			result.ScannedRows += examined
134			if err != nil {
135				return QueryResult{}, err
136			}
137		}
138		result.RowCount = len(result.Rows)
139		return result, nil
140	}
141	
142	func columnIndices(schema Schema, names []string) []int {
143		out := make([]int, 0, len(names))
144		for _, name := range names {
145			out = append(out, columnIndex(schema, name))
146		}
147		return out
148	}
149	
150	// scanGroup walks the rows of one row group and calls visit for every row that
151	// satisfies all predicates, returning the number of rows it examined. A row is
152	// examined only when every column the query reads has a decoded value for it;
153	// rows that live in a pruned or budget-excluded page can never match and are
154	// not examined. Scanning stops as soon as visit returns false.
155	func scanGroup(schema Schema, rowCount int, columns []decodedColumn, predicates []Predicate, visit func(row int, values []Value) bool) (int, error) {
156		type predicateColumn struct {
157			index  int
158			column Column
159		}
160		predicateColumns := make([]predicateColumn, 0, len(predicates))
161		for _, predicate := range predicates {
162			index := columnIndex(schema, predicate.Column)
163			column, _ := schema.Column(predicate.Column)
164			predicateColumns = append(predicateColumns, predicateColumn{index, column})
165		}
166		examined := 0
167		values := make([]Value, len(schema.Columns))
168		for row := 0; row < rowCount; row++ {
169			available := true
170			for c := range columns {
171				if !columns[c].needed {
172					continue
173				}
174				value, ok := columns[c].valueAt(row)
175				if !ok {
176					available = false
177					break
178				}
179				values[c] = value
180			}
181			if !available {
182				continue
183			}
184			examined++
185			matched := true
186			for i, entry := range predicateColumns {
187				if !predicates[i].matches(values[entry.index], entry.column.Type) {
188					matched = false
189					break
190				}
191			}
192			if !matched {
193				continue
194			}
195			if !visit(row, values) {
196				return examined, nil
197			}
198		}
199		return examined, nil
200	}
201	
202	// decodeGroup decodes every page that survives pushdown and the page budget,
203	// for the columns the query needs.
204	func decodeGroup(table *Table, group RowGroup, query Query, pushdown bool) ([]decodedColumn, decodeStats, error) {
205		columns := make([]decodedColumn, len(table.Schema.Columns))
206		stats := decodeStats{}
207		if len(group.Pages) == 0 {
208			return columns, stats, nil
209		}
210		width := pageWidth(group)
211		budget := -1
212		if query.Pages != nil {
213			budget = *query.Pages
214		}
215		for index, column := range table.Schema.Columns {
216			predicates := predicatesFor(query, column.Name)
217			needed := len(predicates) > 0 || columnNeeded(query, column.Name)
218			columns[index].needed = needed
219			if !needed {
220				continue
221			}
222			for _, header := range group.Pages[column.Name] {
223				// The budget counts pages by their index, so a pruned page still
224				// consumes its slot and both scan modes cover the same rows.
225				if budget >= 0 && int(header.PageIndex) >= budget {
226					break
227				}
228				if pushdown && !pagePossible(header, predicates) {
229					stats.skippedPages++
230					continue
231				}
232				values, err := table.parsed.pageValues(header)
233				if err != nil {
234					return nil, stats, err
235				}
236				if len(values) != int(header.ValueCount) {
237					return nil, stats, Formatf("page %d decoded %d values but declares %d", header.PageIndex, len(values), header.ValueCount)
238				}
239				columns[index].segments = append(columns[index].segments, decodedSegment{
240					start:  int(header.PageIndex) * width,
241					values: values,
242				})
243				stats.decodedPages++
244			}
245		}
246		return columns, stats, nil
247	}
248	
249	// pageWidth is the page capacity recorded for a row group. Reading it back
250	// instead of guessing keeps page index to row offset mapping exact.
251	func pageWidth(group RowGroup) int { return normalizedPageWidth(group.PageValues) }
252	
253	func predicatesFor(query Query, column string) []Predicate {
254		var out []Predicate
255		for _, predicate := range query.Predicates {
256			if predicate.Column == column {
257				out = append(out, predicate)
258			}
259		}
260		return out
261	}
262	
263	func projectionNeeds(query Query, column string) bool {
264		for _, name := range query.Projection {
265			if name == column {
266				return true
267			}
268		}
269		return false
270	}
271	
272	// columnNeeded reports whether a query reads a column through its projection or
273	// through an aggregate.
274	func columnNeeded(query Query, column string) bool {
275		if projectionNeeds(query, column) {
276			return true
277		}
278		for _, aggregate := range query.Aggregates {
279			if aggregate.Column == column {
280				return true
281			}
282		}
283		return false
284	}
285	
286	// pagePossible applies the page statistics recorded in the footer. It returns
287	// false only when no row in the page can satisfy every predicate on the column.
288	func pagePossible(header PageHeader, predicates []Predicate) bool {
289		if len(predicates) == 0 {
290			return true
291		}
292		if header.ValueCount == 0 {
293			return false
294		}
295		stats := header.stats
296		for _, predicate := range predicates {
297			if !predicate.pageMatches(stats, int64(header.ValueCount)) {
298				return false
299			}
300		}
301		return true
302	}
303	
304	func executeAggregates(table *Table, query Query, pushdown bool) (QueryResult, error) {
305		result := QueryResult{Columns: []string{}, Rows: []map[string]any{}, Pushdown: pushdown}
306		state := make([]aggregateState, len(query.Aggregates))
307		// Result columns are named <func>_<column>, or <func> for count over every
308		// row. A repeated name gets a numeric suffix so the row object stays
309		// unambiguous.
310		used := map[string]int{}
311		for i, aggregate := range query.Aggregates {
312			name := aggregate.Func
313			if aggregate.Column != "" {
314				name = aggregate.Func + "_" + aggregate.Column
315			}
316			used[name]++
317			if used[name] > 1 {
318				name = fmt.Sprintf("%s_%d", name, used[name])
319			}
320			result.Columns = append(result.Columns, name)
321			state[i] = aggregateState{
322				function: aggregate.Func,
323				column:   aggregate.Column,
324				index:    columnIndex(table.Schema, aggregate.Column),
325				min:      NullValue(),
326				max:      NullValue(),
327			}
328		}
329		for groupIndex := range table.parsed.rowGroups {
330			group := table.parsed.rowGroups[groupIndex]
331			if group.RowCount == 0 {
332				continue
333			}
334			result.ScannedGroups++
335			columns, stats, err := decodeGroup(table, group, query, pushdown)
336			if err != nil {
337				return QueryResult{}, err
338			}
339			result.ScannedPages += stats.decodedPages
340			result.SkippedPages += stats.skippedPages
341			examined, err := scanGroup(table.Schema, group.RowCount, columns, query.Predicates, func(_ int, values []Value) bool {
342				result.MatchedRows++
343				for i := range state {
344					state[i].add(values)
345				}
346				return true
347			})
348			result.ScannedRows += examined
349			if err != nil {
350				return QueryResult{}, err
351			}
352		}
353		row := map[string]any{}
354		for i := range state {
355			row[result.Columns[i]] = state[i].value()
356		}
357		result.Rows = append(result.Rows, row)
358		result.RowCount = 1
359		return result, nil
360	}
361	
362	type aggregateState struct {
363		function string
364		column   string
365		index    int
366		count    int64
367		sum      float64
368		min      Value
369		max      Value
370	}
371	
372	func (a *aggregateState) add(values []Value) {
373		if a.function == AggCount && a.column == "" {
374			a.count++
375			return
376		}
377		if a.index < 0 || a.index >= len(values) {
378			return
379		}
380		value := values[a.index]
381		if a.function == AggCount {
382			if !value.Null {
383				a.count++
384			}
385			return
386		}
387		if value.Null {
388			return
389		}
390		switch a.function {
391		case AggSum:
392			number, ok := value.Number()
393			if !ok {
394				return
395			}
396			a.sum += number
397		case AggMin:
398			if a.min.Null || less(value, a.min) {
399				a.min = value
400			}
401		case AggMax:
402			if a.max.Null || less(a.max, value) {
403				a.max = value
404			}
405		}
406	}
407	
408	func (a *aggregateState) value() any {
409		switch a.function {
410		case AggCount:
411			return a.count
412		case AggSum:
413			return a.sum
414		case AggMin:
415			if a.min.Null {
416				return nil
417			}
418			return a.min.JSON()
419		default:
420			if a.max.Null {
421				return nil
422			}
423			return a.max.JSON()
424		}
425	}
