211	// encodeColumn splits one column of a row group into pages, choosing the
212	// smallest legal encoding per page unless an encoding was forced.
213	func encodeColumn(typ string, values []Value, maxPerPage int, forced string) ([]PageHeader, [][]byte, PageStats, error) {
214		if maxPerPage <= 0 {
215			maxPerPage = DefaultMaxPage
216		}
217		var headers []PageHeader
218		var bodies [][]byte
219		groupStats := PageStats{Min: NullValue(), Max: NullValue()}
220		for start, index := 0, uint32(0); start < len(values); index++ {
221			end := start + maxPerPage
222			if end > len(values) {
223				end = len(values)
224			}
225			chunk := values[start:end]
226			encoding := forced
227			if encoding == "" {
228				encoding = chooseEncoding(chunk, typ)
229			}
230			payload, stats, err := encodePage(chunk, typ, encoding)
231			if err != nil {
232				return nil, nil, PageStats{}, err
233			}
234			header := PageHeader{
235				PageIndex:  index,
236				ValueCount: uint32(len(chunk)),
237				Encoding:   payload.Encoding,
238				DictSize:   payload.DictSize,
239				RunCount:   payload.RunCount,
240				IndexBits:  payload.IndexBits,
241				Payload:    uint64(len(payload.Payload)),
242				stats:      stats,
243			}
244			bodies = append(bodies, buildPageBytes(header, payload.Payload))
245			headers = append(headers, header)
246			groupStats.Nulls += stats.Nulls
247			if stats.Set {
248				if !groupStats.Set {
249					groupStats.Set, groupStats.Min, groupStats.Max = true, stats.Min, stats.Max
250				} else {
251					if less(stats.Min, groupStats.Min) {
252						groupStats.Min = stats.Min
253					}
254					if less(groupStats.Max, stats.Max) {
255						groupStats.Max = stats.Max
256					}
257				}
258			}
259			start = end
260		}
261		return headers, bodies, groupStats, nil
262	}
263	
264	func buildPageBytes(h PageHeader, payload []byte) []byte {
265		w := &fileWriter{}
266		w.u32(h.PageIndex)
267		w.u32(h.ValueCount)
268		w.u8(encodingCode(h.Encoding))
269		switch h.Encoding {
270		case EncodingDictionary:
271			w.u32(h.DictSize)
272			w.u8(h.IndexBits)
273		case EncodingRLE:
274			w.u32(h.RunCount)
275		}
276		w.u64(uint64(len(payload)))
277		w.raw(payload)
278		return w.buf.Bytes()
279	}
