281	func chooseEncoding(values []Value, typ string) string {
282		if len(values) == 0 {
283			return EncodingPlain
284		}
285		nonNull := nonNullIndices(values)
286		costs := map[string]int{}
287		plain, _, err := encodePage(values, typ, EncodingPlain)
288		if err != nil {
289			return EncodingPlain
290		}
291		costs[EncodingPlain] = len(plain.Payload)
292		if DistinctCount(values) < len(nonNull) {
293			if dict, _, err := encodePage(values, typ, EncodingDictionary); err == nil {
294				costs[EncodingDictionary] = len(dict.Payload)
295			}
296		}
297		if SortedForRLE(values) {
298			if rle, _, err := encodePage(values, typ, EncodingRLE); err == nil {
299				costs[EncodingRLE] = len(rle.Payload)
300			}
301		}
302		best := EncodingPlain
303		// The cheapest payload wins; ties are broken deterministically in favour of
304		// dictionary, then rle, then plain.
305		for _, candidate := range []string{EncodingRLE, EncodingDictionary} {
306			if cost, ok := costs[candidate]; ok && cost <= costs[best] {
307				best = candidate
308			}
309		}
310		return best
311	}
