313	// WriteFile writes a complete Columna file. forced optionally pins the
314	// encoding of individual columns.
315	func WriteFile(path string, schema Schema, groups [][]Row, maxPerPage int, forced map[string]string) (*File, error) {
316		rowGroups, columnStats, err := buildRowGroups(schema, groups, maxPerPage, forced)
317		if err != nil {
318			return nil, err
319		}
320		raw, err := renderFile(schema, rowGroups, columnStats, nil)
321		if err != nil {
322			return nil, err
323		}
324		if err := writeAtomically(path, raw); err != nil {
325			return nil, err
326		}
327		return ReadFile(path)
328	}
329	
330	// buildRowGroups encodes the given batches of rows. Page offsets are relative
331	// to the start of the row group data area.
332	func buildRowGroups(schema Schema, groups [][]Row, maxPerPage int, forced map[string]string) ([]RowGroup, []ColumnStats, error) {
333		if err := schema.Validate(); err != nil {
334			return nil, nil, err
335		}
336		rowGroups := make([]RowGroup, 0, len(groups))
337		columnStats := make([]ColumnStats, len(schema.Columns))
338		for i, c := range schema.Columns {
339			columnStats[i] = ColumnStats{Name: c.Name, Type: c.Type, Min: NullValue(), Max: NullValue()}
340		}
341		for _, rows := range groups {
342			group := RowGroup{RowCount: len(rows), PageValues: normalizedPageWidth(maxPerPage), Pages: map[string][]PageHeader{}}
343			for columnIndex, column := range schema.Columns {
344				values := make([]Value, len(rows))
345				for i, row := range rows {
346					if len(row) != len(schema.Columns) {
347						return nil, nil, Validationf("row %d has %d values, expected %d", i, len(row), len(schema.Columns))
348					}
349					if row[columnIndex].Null && !column.Nullable {
350						return nil, nil, Validationf("column %q is not nullable", column.Name)
351					}
352					values[i] = row[columnIndex]
353				}
354				headers, bodies, stats, err := encodeColumn(column.Type, values, maxPerPage, forced[column.Name])
355				if err != nil {
356					return nil, nil, err
357				}
358				// Page offsets stay relative to the row group; renderFile adds
359				// the row group base offset when it lays the data area out.
360				for i := range headers {
361					headers[i].Offset = uint64(len(group.raw))
362					headers[i].Length = uint64(len(bodies[i]))
363					group.raw = append(group.raw, bodies[i]...)
364				}
365				group.Pages[column.Name] = headers
366				entry := &columnStats[columnIndex]
367				entry.Pages += len(headers)
368				entry.RowCount += int64(len(rows))
369				entry.NullCount += stats.Nulls
370				if stats.Set {
371					if !entry.Min.Null && entry.Min.Kind == "" {
372						return nil, nil, errorf(CodeInternal, "column statistics were not initialised")
373					}
374					if entry.Min.Null {
375						entry.Min, entry.Max = stats.Min, stats.Max
376					} else {
377						if less(stats.Min, entry.Min) {
378							entry.Min = stats.Min
379						}
380						if less(entry.Max, stats.Max) {
381							entry.Max = stats.Max
382						}
383					}
384				}
385			}
386			rowGroups = append(rowGroups, group)
387		}
388		return rowGroups, columnStats, nil
389	}
390	
391	// renderFile serialises a whole Columna file: header, every row group's pages,
392	// the footer, the trailer and the payload checksum. Page offsets held in memory
393	// are relative to their row group; the footer records absolute offsets. data is
394	// the data area that the leading row groups must reproduce byte for byte: the
395	// append path passes the original file's data area, so a mis-copied or
396	// mis-rebased row group is rejected instead of silently corrupting the file.
397	// Pass nil when the file is written from scratch.
398	func renderFile(schema Schema, groups []RowGroup, columnStats []ColumnStats, data []byte) ([]byte, error) {
399		w := &fileWriter{}
400		w.raw(Magic[:])
401		w.u16(FormatVersion)
402		w.u16(uint16(len(schema.Columns)))
403		for _, group := range groups {
404			w.raw(group.raw)
405		}
406		if data != nil {
407			written := w.buf.Bytes()[FileHeaderSize:]
408			if len(written) < len(data) || !bytes.Equal(written[:len(data)], data) {
409				return nil, errorf(CodeInternal, "row group bytes do not match the recorded data area (%d vs %d)", len(written), len(data))
410			}
411		}
412		laid := make([]RowGroup, 0, len(groups))
413		base := uint64(FileHeaderSize)
414		for _, group := range groups {
415			copied := RowGroup{RowCount: group.RowCount, PageValues: group.PageValues, Pages: map[string][]PageHeader{}}
416			for name, headers := range group.Pages {
417				shifted := make([]PageHeader, len(headers))
418				for i, h := range headers {
419					// In-memory headers carry offsets relative to the start of
420					// their row group; the footer records absolute offsets.
421					h.Offset += base
422					shifted[i] = h
423				}
424				copied.Pages[name] = shifted
425			}
426			laid = append(laid, copied)
427			base += uint64(len(group.raw))
428		}
429		footerOffset := w.buf.Len()
430		footer := buildFooter(schema, laid, columnStats)
431		w.raw(footer)
432		w.u32(uint32(len(footer)))
433		w.u64(uint64(footerOffset))
434		w.u32(uint32(len(schema.Columns)))
435		w.u32(uint32(len(laid)))
436		w.raw([]byte(FooterMagic))
437		sum := sha256.Sum256(w.buf.Bytes())
438		w.raw(sum[:])
439		return w.buf.Bytes(), nil
440	}
441	
442	func normalizedPageWidth(maxPerPage int) int {
443		if maxPerPage <= 0 {
444			return DefaultMaxPage
445		}
446		return maxPerPage
447	}
448	
449	// dataOrder lists the schema columns so the data area order is deterministic.
450	func dataOrder(schema Schema) []string {
451		names := make([]string, len(schema.Columns))
452		for i, c := range schema.Columns {
453			names[i] = c.Name
454		}
455		return names
456	}
457	
458	// writeAtomically writes raw next to path and renames it over the target only
459	// after the temporary file parses, so a file that fails validation never
460	// replaces a readable one.
461	func writeAtomically(path string, raw []byte) error {
462		temp := path + ".tmp"
463		if err := os.WriteFile(temp, raw, 0o644); err != nil {
464			return errorf(CodeInternal, "cannot write %s: %v", temp, err)
465		}
466		if _, err := ReadFile(temp); err != nil {
467			os.Remove(temp)
468			return err
469		}
470		if err := os.Rename(temp, path); err != nil {
471			os.Remove(temp)
472			return errorf(CodeInternal, "cannot replace %s: %v", path, err)
473		}
474		return nil
475	}
476	
477	// AppendRows rewrites path so that it holds the existing row groups followed
478	// by one new row group. The result is byte-identical to writing every batch in
479	// a single call.
480	func AppendRows(path string, schema Schema, rows []Row, maxPerPage int, forced map[string]string) (*File, error) {
481		existing, err := ReadFile(path)
482		if err != nil {
483			return nil, err
484		}
485		if !schema.Equal(existing.schema) {
486			return nil, Validationf("rows do not match the schema of %s", path)
487		}
488		old, err := os.ReadFile(path)
489		if err != nil {
490			return nil, errorf(CodeInternal, "cannot read %s: %v", path, err)
491		}
492		trailerAt := len(old) - ChecksumSize - FooterMagicSize - FooterTrailerSize
493		if trailerAt < 0 || string(old[trailerAt+FooterTrailerSize:trailerAt+FooterTrailerSize+FooterMagicSize]) != FooterMagic {
494			return nil, Formatf("file %s has no footer magic", path)
495		}
496		footerOffset := int(binary.BigEndian.Uint64(old[trailerAt+4 : trailerAt+12]))
497	
498		newGroups, newStats, err := buildRowGroups(schema, [][]Row{rows}, maxPerPage, forced)
499		if err != nil {
500			return nil, err
501		}
502		combinedStats := append([]ColumnStats{}, existing.stats.Columns...)
503		for i := range combinedStats {
504			combinedStats[i].Pages += newStats[i].Pages
505			combinedStats[i].NullCount += newStats[i].NullCount
506			combinedStats[i].RowCount += newStats[i].RowCount
507			if newStats[i].Min.Null {
508				continue
509			}
510			if combinedStats[i].Min.Null {
511				combinedStats[i].Min, combinedStats[i].Max = newStats[i].Min, newStats[i].Max
512				continue
513			}
514			if less(newStats[i].Min, combinedStats[i].Min) {
515				combinedStats[i].Min = newStats[i].Min
516			}
517			if less(combinedStats[i].Max, newStats[i].Max) {
518				combinedStats[i].Max = newStats[i].Max
519			}
520		}
521		combined := make([]RowGroup, 0, len(existing.rowGroups)+len(newGroups))
522		for _, group := range existing.rowGroups {
523			raw, base, err := slicesOf(old, existing.schema, group)
524			if err != nil {
525				return nil, err
526			}
527			rebuilt, err := rebasedGroup(group, base, raw)
528			if err != nil {
529				return nil, err
530			}
531			combined = append(combined, rebuilt)
532		}
533		combined = append(combined, newGroups...)
534		// The leading row groups are byte-for-byte copies of the old data area, so
535		// re-rendering them must reproduce that area exactly. renderFile enforces
536		// it; the header prologue is not part of the data area.
537		out, err := renderFile(existing.schema, combined, combinedStats, old[FileHeaderSize:footerOffset])
538		if err != nil {
539			return nil, err
540		}
541		if err := writeAtomically(path, out); err != nil {
542			return nil, err
543		}
544		return ReadFile(path)
545	}
546	
547	// slicesOf returns the encoded data area of an existing row group so the append
548	// path can copy it verbatim, together with the absolute file offset the area
549	// starts at. The data area is the contiguous byte range that covers every page
550	// of every column of the group.
551	func slicesOf(raw []byte, schema Schema, group RowGroup) ([]byte, uint64, error) {
552		width := normalizedPageWidth(group.PageValues)
553		start := uint64(len(raw))
554		end := uint64(0)
555		for _, name := range dataOrder(schema) {
556			headers := group.Pages[name]
557			for p, header := range headers {
558				if int(header.PageIndex) != p {
559					return nil, 0, Formatf("column %q page %d breaks the page sequence", name, header.PageIndex)
560				}
561				if p < len(headers)-1 && int(header.ValueCount) != width {
562					return nil, 0, Formatf("column %q page %d holds %d values, expected %d", name, header.PageIndex, header.ValueCount, width)
563				}
564				if header.Offset+header.Length > uint64(len(raw)) {
565					return nil, 0, Formatf("column %q page %d overruns the data area", name, header.PageIndex)
566				}
567				if header.Offset < start {
568					start = header.Offset
569				}
570				if header.Offset+header.Length > end {
571					end = header.Offset + header.Length
572				}
573			}
574		}
575		if end <= start {
576			return nil, 0, nil
577		}
578		return append([]byte{}, raw[start:end]...), start, nil
579	}
580	
581	// rebasedGroup converts a row group parsed from a file into the in-memory write
582	// representation: the encoded page bytes are kept verbatim and the absolute
583	// offsets recorded in the footer are turned back into offsets relative to the
584	// start of the row group, which is what renderFile lays out.
585	func rebasedGroup(group RowGroup, base uint64, raw []byte) (RowGroup, error) {
586		out := RowGroup{
587			RowCount:   group.RowCount,
588			PageValues: group.PageValues,
589			Pages:      make(map[string][]PageHeader, len(group.Pages)),
590			raw:        raw,
591		}
592		for name, headers := range group.Pages {
593			shifted := make([]PageHeader, len(headers))
594			for i, header := range headers {
595				if header.Offset < base || header.Offset+header.Length > base+uint64(len(raw)) {
596					return RowGroup{}, Formatf("column %q page %d lies outside its row group", name, header.PageIndex)
597				}
598				header.Offset -= base
599				shifted[i] = header
600			}
601			out.Pages[name] = shifted
602		}
603		return out, nil
604	}
605	
606	// buildFooter serialises the footer: version, schema, page tables and column
607	// statistics. Every page table entry carries the page's encoding header and
608	// its recorded statistics, so a reader never has to touch a page header.
609	func buildFooter(schema Schema, groups []RowGroup, stats []ColumnStats) []byte {
610		w := &fileWriter{}
611		w.u32(FormatVersion)
612		w.u16(uint16(len(schema.Columns)))
613		for _, c := range schema.Columns {
614			w.str(c.Name)
615			w.u8(typeCode(c.Type))
616			flag := uint8(0)
617			if c.Nullable {
618				flag = 1
619			}
620			w.u8(flag)
621		}
622		w.u32(uint32(len(groups)))
623		for _, group := range groups {
624			w.u64(uint64(group.RowCount))
625			w.u32(uint32(normalizedPageWidth(group.PageValues)))
626			w.u32(uint32(len(schema.Columns)))
627			for _, column := range schema.Columns {
628				headers := group.Pages[column.Name]
629				w.u32(uint32(len(headers)))
630				for _, h := range headers {
631					w.u32(h.PageIndex)
632					w.u32(h.ValueCount)
633					w.u8(encodingCode(h.Encoding))
634					switch h.Encoding {
635					case EncodingDictionary:
636						w.u32(h.DictSize)
637						w.u8(h.IndexBits)
638					case EncodingRLE:
639						w.u32(h.RunCount)
640					}
641					w.u64(h.Offset)
642					w.u64(h.Length)
643					w.u64(h.Payload)
644					w.u64(uint64(h.stats.Nulls))
645					encodeStatValue(w, h.stats.Min)
646					encodeStatValue(w, h.stats.Max)
647				}
648			}
649		}
650		for _, entry := range stats {
651			w.str(entry.Name)
652			w.u8(typeCode(entry.Type))
653			w.u64(uint64(entry.Pages))
654			w.u64(uint64(entry.RowCount))
655			w.u64(uint64(entry.NullCount))
656			encodeStatValue(w, entry.Min)
657			encodeStatValue(w, entry.Max)
658		}
659		return w.buf.Bytes()
660	}
661	
662	// encodeStatValue writes one boundary statistic: an absence flag followed by
663	// the value in plain layout. Strings are prefixed with a u16 length that
664	// includes their NUL terminator because their plain layout is variable sized;
665	// int64, float64 and bool values are fixed sized. A string longer than the
666	// u16 length can express is recorded as absent, which only ever makes the
667	// statistic more conservative.
668	func encodeStatValue(w *fileWriter, v Value) {
669		if v.Null || v.Kind == "" || (v.Kind == TypeString && len(v.Str)+1 > 0xffff) {
670			w.u8(0)
671			return
672		}
673		w.u8(1)
674		if v.Kind == TypeString {
675			w.u16(uint16(len(v.Str) + 1))
676		}
677		w.raw(encodePlainValues([]Value{v}, []int{0}))
678	}
679	
680	// ReadFile parses a Columna file, validating magic, version, footer and the
681	// payload checksum.
682	func ReadFile(path string) (*File, error) {
683		raw, err := os.ReadFile(path)
684		if err != nil {
685			return nil, errorf(CodeNotFound, "table %s does not exist", path)
686		}
687		if len(raw) < 12+FooterMagicSize+FooterTrailerSize+ChecksumSize {
688			return nil, Formatf("file %s is too small to be a Columna file", path)
689		}
690		if !bytes.Equal(raw[:8], Magic[:]) {
691			return nil, Formatf("file %s has a bad magic number", path)
692		}
693		if version := binary.BigEndian.Uint16(raw[8:10]); version != FormatVersion {
694			return nil, Formatf("file %s uses unsupported format version %d", path, version)
695		}
696		want := sha256.Sum256(raw[:len(raw)-ChecksumSize])
697		if !bytes.Equal(want[:], raw[len(raw)-ChecksumSize:]) {
698			return nil, Formatf("file %s failed its payload checksum", path)
699		}
700		trailerAt := len(raw) - ChecksumSize - FooterMagicSize - FooterTrailerSize
701		trailer := raw[trailerAt : trailerAt+FooterTrailerSize]
702		if string(raw[trailerAt+FooterTrailerSize:len(raw)-ChecksumSize]) != FooterMagic {
703			return nil, Formatf("file %s has no footer magic", path)
704		}
705		footerLength := int(binary.BigEndian.Uint32(trailer[0:4]))
706		footerOffset := int(binary.BigEndian.Uint64(trailer[4:12]))
707		columnCount := int(binary.BigEndian.Uint32(trailer[12:16]))
708		groupCount := int(binary.BigEndian.Uint32(trailer[16:20]))
709		if footerOffset < 0 || footerOffset+footerLength != trailerAt {
710			return nil, Formatf("file %s footer offsets do not add up to the file size", path)
711		}
712		parsed, err := parseFooter(raw[footerOffset : footerOffset+footerLength])
713		if err != nil {
714			return nil, err
715		}
716		parsed.path = path
717		parsed.stats.FileSize = int64(len(raw))
718		if columnCount != len(parsed.schema.Columns) || groupCount != len(parsed.rowGroups) {
719			return nil, Formatf("file %s trailer disagrees with its footer", path)
720		}
721		rowTotal := int64(0)
722		encodings := map[string]bool{}
723		for g := range parsed.rowGroups {
724			rowTotal += int64(parsed.rowGroups[g].RowCount)
725			width := normalizedPageWidth(parsed.rowGroups[g].PageValues)
726			for _, column := range parsed.schema.Columns {
727				headers := parsed.rowGroups[g].Pages[column.Name]
728				for i := range headers {
729					if int(headers[i].PageIndex) != i {
730						return nil, Formatf("row group %d column %s page %d breaks the page sequence", g, column.Name, headers[i].PageIndex)
731					}
732					if i < len(headers)-1 && int(headers[i].ValueCount) != width {
733						return nil, Formatf("row group %d column %s page %d holds %d values, expected %d", g, column.Name, headers[i].PageIndex, headers[i].ValueCount, width)
734					}
735					if headers[i].Offset+headers[i].Length > uint64(footerOffset) {
736						return nil, Formatf("row group %d column %s page %d overruns the data area", g, column.Name, headers[i].PageIndex)
737					}
738					headers[i].ColumnType = column.Type
739					headers[i].Path = path
740					encodings[headers[i].Encoding] = true
741				}
742				parsed.rowGroups[g].Pages[column.Name] = headers
743			}
744		}
745		parsed.stats.RowCount = rowTotal
746		parsed.stats.RowGroupCount = len(parsed.rowGroups)
747		parsed.stats.Encodings = []string{}
748		for _, candidate := range []string{EncodingPlain, EncodingDictionary, EncodingRLE} {
749			if encodings[candidate] {
750				parsed.stats.Encodings = append(parsed.stats.Encodings, candidate)
751			}
752		}
753		return parsed, nil
754	}
755	
756	const FooterMagicSize = len(FooterMagic)
757	
758	func parseFooter(raw []byte) (*File, error) {
759		r := &footerReader{raw: raw}
760		if version := r.u32(); version != FormatVersion {
761			return nil, Formatf("footer version %d is unsupported", version)
762		}
763		columnCount := int(r.u16())
764		if r.err != nil {
765			return nil, Formatf("footer is truncated")
766		}
767		if columnCount <= 0 {
768			return nil, Formatf("footer declares %d columns", columnCount)
769		}
770		schema := Schema{}
771		for i := 0; i < columnCount; i++ {
772			name := r.str()
773			code := r.u8()
774			typ, err := typeName(code)
775			if err != nil {
776				return nil, err
777			}
778			nullable := r.u8() == 1
779			schema.Columns = append(schema.Columns, Column{Name: name, Type: typ, Nullable: nullable})
780		}
781		if r.err != nil {
782			return nil, Formatf("footer schema block is truncated")
783		}
784		groupCount := int(r.u32())
785		groups := make([]RowGroup, 0, groupCount)
786		for g := 0; g < groupCount; g++ {
787			rowCount := int(r.u64())
788			pageValues := normalizedPageWidth(int(r.u32()))
789			columns := int(r.u32())
790			if columns != len(schema.Columns) {
791				return nil, Formatf("row group %d lists %d columns, expected %d", g, columns, len(schema.Columns))
792			}
793			group := RowGroup{RowCount: rowCount, PageValues: pageValues, Pages: map[string][]PageHeader{}}
794			for c := 0; c < len(schema.Columns); c++ {
795				column := schema.Columns[c]
796				pageCount := int(r.u32())
797				headers := make([]PageHeader, 0, pageCount)
798				for p := 0; p < pageCount; p++ {
799					header := PageHeader{}
800					header.PageIndex = r.u32()
801					header.ValueCount = r.u32()
802					encoding, err := encodingName(r.u8())
803					if err != nil {
804						return nil, err
805					}
806					header.Encoding = encoding
807					switch encoding {
808					case EncodingDictionary:
809						header.DictSize = r.u32()
810						header.IndexBits = r.u8()
811					case EncodingRLE:
812						header.RunCount = r.u32()
813					}
814					header.Offset = r.u64()
815					header.Length = r.u64()
816					header.Payload = r.u64()
817					header.stats.Nulls = int64(r.u64())
818					header.stats.Min, err = r.statValue(column.Type)
819					if err != nil {
820						return nil, err
821					}
822					header.stats.Max, err = r.statValue(column.Type)
823					if err != nil {
824						return nil, err
825					}
826					header.stats.Set = !header.stats.Min.Null && !header.stats.Max.Null
827					headers = append(headers, header)
828				}
829				group.Pages[column.Name] = headers
830			}
831			groups = append(groups, group)
832		}
833		stats := make([]ColumnStats, len(schema.Columns))
834		for i, column := range schema.Columns {
835			name := r.str()
836			if name != column.Name {
837				return nil, Formatf("statistics block %d is for %q, expected %q", i, name, column.Name)
838			}
839			code := r.u8()
840			typ, err := typeName(code)
841			if err != nil {
842				return nil, err
843			}
844			if typ != column.Type {
845				return nil, Formatf("statistics for %q disagree about the type", name)
846			}
847			entry := ColumnStats{Name: name, Type: typ}
848			entry.Pages = int(r.u64())
849			entry.RowCount = int64(r.u64())
850			entry.NullCount = int64(r.u64())
851			entry.Min, err = r.statValue(typ)
852			if err != nil {
853				return nil, err
854			}
855			entry.Max, err = r.statValue(typ)
856			if err != nil {
857				return nil, err
858			}
859			stats[i] = entry
860		}
861		if r.err != nil {
862			return nil, r.err
863		}
864		return &File{
865			schema:    schema,
866			rowGroups: groups,
867			stats:     FileStats{Columns: stats},
868		}, nil
869	}
870	
871	type footerReader struct {
872		raw []byte
873		pos int
874		err error
875	}
876	
877	func (r *footerReader) take(n int) []byte {
878		if r.err != nil {
879			return make([]byte, n)
880		}
881		if r.pos+n > len(r.raw) {
882			r.err = Formatf("footer is truncated")
883			return make([]byte, n)
884		}
885		out := r.raw[r.pos : r.pos+n]
886		r.pos += n
887		return out
888	}
889	
890	func (r *footerReader) u8() uint8   { return r.take(1)[0] }
891	func (r *footerReader) u16() uint16 { return binary.BigEndian.Uint16(r.take(2)) }
892	func (r *footerReader) u32() uint32 { return binary.BigEndian.Uint32(r.take(4)) }
893	func (r *footerReader) u64() uint64 { return binary.BigEndian.Uint64(r.take(8)) }
894	
895	func (r *footerReader) str() string { return string(r.take(int(r.u16()))) }
896	
897	func (r *footerReader) statValue(typ string) (Value, error) {
898		present := r.u8()
899		if r.err != nil {
900			return NullValue(), r.err
901		}
902		if present == 0 {
903			return NullValue(), nil
904		}
905		var size int
906		switch typ {
907		case TypeString:
908			// The recorded length includes the NUL terminator of the plain
909			// layout, so the decoder sees a complete value.
910			size = int(r.u16())
911		case TypeBool:
912			size = 1
913		default:
914			size = 8
915		}
916		body := r.take(size)
917		if r.err != nil {
918			return NullValue(), r.err
919		}
920		values, err := decodePlainValues(body, typ, 1)
921		if err != nil {
922			return NullValue(), err
923		}
924		return values[0], nil
925	}
926	
927	// pageValues reads and decodes the payload of one page.
928	func (p *File) pageValues(h PageHeader) ([]Value, error) {
929		file, err := os.Open(p.path)
930		if err != nil {
931			return nil, errorf(CodeInternal, "cannot read %s: %v", p.path, err)
932		}
933		defer file.Close()
934		payload := make([]byte, h.Payload)
935		payloadOffset := int64(h.Offset) + int64(h.Length) - int64(h.Payload)
936		if _, err := file.ReadAt(payload, payloadOffset); err != nil {
937			return nil, Formatf("page %d payload is truncated: %v", h.PageIndex, err)
938		}
939		return decodePage(h, payload, int(h.ValueCount), h.ColumnType)
940	}
941	
942	// Checksum returns the hex SHA-256 recorded in the file trailer.
943	func Checksum(path string) (string, error) {
944		raw, err := os.ReadFile(path)
945		if err != nil {
946			return "", errorf(CodeNotFound, "table %s does not exist", path)
947		}
948		if len(raw) < ChecksumSize {
949			return "", Formatf("file %s is too small", path)
950		}
951		return hex.EncodeToString(raw[len(raw)-ChecksumSize:]), nil
952	}
953

