298		}
299		if number, err := strconv.ParseInt(text, 10, 64); err == nil {
300			value := columna.IntValue(number)
301			return &value, nil
302		}
303		if number, err := strconv.ParseFloat(text, 64); err == nil {
304			value := columna.FloatValue(number)
305			return &value, nil
306		}
307		value := columna.StringValue(strings.Trim(text, `"'`))
308		return &value, nil
