161	// groupedCandidate builds a candidate of n row groups of 100 rows each.
162	func groupedCandidate(name string, groups int) columna.SourceCandidate {
163		candidate := columna.SourceCandidate{Name: name, RowCount: int64(100 * groups)}
164		for i := 0; i < groups; i++ {
165			candidate.RowGroups = append(candidate.RowGroups, columna.RowGroupStats{
166				RowCount: 100,
167				Columns:  []columna.ColumnCostStats{intChunk("id", 800, 0, 100, 1, 100)},
168			})
169		}
170		return candidate
171	}
